import Header from './header' // Server Component — no JS shipped
import Footer from './footer' // Server Component — no JS shipped
import SearchBar from './search-bar' // 'use client' — only this in bundle
export default function Layout({ children }) { return <><Header /><SearchBar />{children}<Footer /></> }

import { Inter } from 'next/font/google'
